    const file = await newDatabasePath();
    await invoke(["add", "--title", "old", "--tags", "x", "--due", "2024-01-01"], file);
    await invoke(["add", "--title", "boundary", "--tags", "x", "--due", "2024-01-02"], file);
    await invoke(["add", "--title", "untagged", "--due", "2023-01-01"], file);
